/**
 * 迁移激活：把可迁移记录一次性改绑到新用途并升至新目录代次；
 * 仅当记录仍在旧用途且版本未变时成功，返回是否更新成功。
 */
boolean rebindRecord(String subjectKey, String oldPurpose, int epoch, String recordKey,
                     int expectedVersion, String newPurpose, long newCatalogGeneration) {
    int updated = jdbc.update(
            "UPDATE consent_record SET purpose = ?, catalog_generation = ?, version = version + 1"
                    + " WHERE subject_key = ? AND purpose = ? AND epoch = ? AND record_key = ?"
                    + " AND version = ?",
            newPurpose, newCatalogGeneration, subjectKey, oldPurpose, epoch, recordKey, expectedVersion);
    return updated > 0;
}

